package org.lira.receiver;
import org.json.*;import java.util.*;
/** Version 2: explicit acknowledgements, drained repeats and durable ordered receipts. */
public final class DictationEngineV2 {
 private final DictationEngine.Clock clock;private final DictationEngine.Audio audio;private final DictationEngine.Display display;private final DictationStateStore store;private final TaskAssetStore assets;
 private DictationEngine.ExplanationAudio explanation;
 public synchronized void setExplanationAudio(DictationEngine.ExplanationAudio value){explanation=value;}
 public synchronized void prepareExplanation(boolean starting)throws Exception{
  if(!active()||!s.getString("state").equals("paused"))throw new IllegalStateException("pause_required_for_explanation");
  if(starting&&(leaseUntil==0||clock.now()>=leaseUntil))throw new IllegalStateException("device_disconnected");
  if(!s.optBoolean("remote_pause_lock")){s.put("remote_pause_lock",true);save();}
 }
 private boolean explanationBusy(){return explanation!=null&&explanation.busy();}
 private boolean replayOnce,debug=false,batch,localCommand; private JSONObject s;private final String boot=UUID.randomUUID().toString();private long generation,nextRepeat,leaseUntil,remindAt;private boolean reminder;private int width=1920,height=1080;
 public DictationEngineV2(DictationEngine.Clock c,DictationEngine.Audio a,DictationEngine.Display d,DictationStateStore st,TaskAssetStore cache,JSONObject recovered)throws Exception {clock=c;audio=a;display=d;store=st;assets=cache;s=recovered;leaseUntil=0;if(s!=null&&active()){s.put("state","paused");event("paused",null);render();}}
 public synchronized void displaySize(int w,int h){width=w;height=h;try{if(s!=null&&current().getString("kind").equals("recognition")&&s.getString("state").equals("waiting_child")){planPage();save();render();}}catch(Exception ignored){}}
 public synchronized void setDebug(boolean value)throws Exception{if(debug==value)return;debug=value;render();}
 public synchronized void toggleDebug()throws Exception{render();}
 public synchronized boolean active(){return s!=null&&!Arrays.asList("completed","cancelled").contains(s.optString("state"));}
 public synchronized JSONObject status()throws Exception{return s==null?new JSONObject().put("state","idle"):new JSONObject(s.toString()).put("debug_enabled",debug);}
 private JSONObject task()throws Exception{return s.getJSONObject("task");}
 private JSONArray steps()throws Exception{return s.getJSONArray("steps");}
 private JSONObject current()throws Exception{return steps().getJSONObject(s.getInt("index"));}
 private void save()throws Exception{store.save(s);}
 private void event(String action,String command)throws Exception {
  long seq=s.optLong("sequence")+1,rev=s.optLong("state_revision")+1;s.put("sequence",seq).put("state_revision",rev);
  JSONObject item=current();JSONObject e=new JSONObject().put("schema_version",2).put("task_id",task().getString("task_id")).put("content_hash",task().getString("content_hash")).put("run_epoch",s.getInt("run_epoch")).put("event_id",UUID.randomUUID().toString()).put("sequence",seq).put("state_revision",rev).put("command_id",command==null||localCommand?JSONObject.NULL:command).put("phase_id",item.getString("phase_id")).put("item_id",item.getString("item_id")).put("action",action).put("state",s.getString("state")).put("actual_repeats",s.optInt("actual_repeats")).put("boot_id",boot).put("session_id",s.getString("session_id")).put("occurred_at",Long.toString(System.currentTimeMillis())).put("elapsed_ms",clock.now());
  if(s.getJSONArray("events").length()>=12000)throw new IllegalStateException("event_capacity");s.getJSONArray("events").put(e);JSONArray log=s.optJSONArray("safe_log");if(log==null)log=new JSONArray();log.put(new JSONObject().put("sequence",seq).put("action",action).put("state",s.getString("state")).put("actual_repeats",s.optInt("actual_repeats")));while(log.length()>20)log.remove(0);s.put("safe_log",log);if(!batch)save();
 }
 private void validateAssets(JSONObject t,JSONObject manifest)throws Exception {
  if(!t.getString("task_id").equals(manifest.getString("task_id"))||!t.getString("content_hash").equals(manifest.getString("content_hash")))throw new IllegalArgumentException("manifest_scope");
  JSONArray required=t.getJSONArray("audio_assets"),list=manifest.getJSONArray("assets");Set<String> ids=new HashSet<>();
  for(int i=0;i<list.length();i++){JSONObject x=list.getJSONObject(i);if(!ids.add(x.getString("asset_id"))||x.getInt("sample_rate")!=24000||x.getInt("channels")!=1||x.getLong("frames")*2!=x.getLong("pcm_bytes")||!assets.begin(t.getString("task_id"),t.getString("content_hash"),x.getString("asset_id"),x.getLong("pcm_bytes"),x.getString("sha256")))throw new IllegalArgumentException("asset_unavailable");}
  for(int i=0;i<required.length();i++){JSONObject r=required.getJSONObject(i);boolean found=false;for(int j=0;j<list.length();j++){JSONObject x=list.getJSONObject(j);if(r.getString("asset_id").equals(x.getString("asset_id"))&&r.getString("sha256").equals(x.getString("sha256")))found=true;}if(!found)throw new IllegalArgumentException("asset_unavailable");}
 }
 public synchronized JSONObject start(JSONObject wrapper)throws Exception {
  JSONObject t=DictationSpec.parse(wrapper.getJSONObject("task")).task;
  JSONArray history=s==null?new JSONArray():s.optJSONArray("history");if(history==null)history=new JSONArray();else history=new JSONArray(history.toString());for(int h=0;h<history.length();h++){JSONObject old=history.getJSONObject(h);if(old.getString("task_id").equals(t.getString("task_id"))){if(!old.getString("content_hash").equals(t.getString("content_hash")))throw new IllegalArgumentException("retired_conflict");return new JSONObject().put("retired",true).put("state",old.getString("state"));}}if(s!=null){if(task().getString("task_id").equals(t.getString("task_id"))){if(!task().getString("content_hash").equals(t.getString("content_hash"))||s.getInt("run_epoch")!=wrapper.getInt("run_epoch"))throw new IllegalArgumentException("task_conflict");return status();}if(active()||s.getJSONArray("events").length()>0)throw new IllegalStateException("task_receipt_retained");if(history.length()>=1000)throw new IllegalStateException("receipt_capacity");history.put(new JSONObject().put("task_id",task().getString("task_id")).put("content_hash",task().getString("content_hash")).put("state",s.getString("state")));}
  validateAssets(t,wrapper.getJSONObject("manifest"));JSONArray steps=new JSONArray(),phases=t.getJSONArray("phases");
  for(int i=0;i<phases.length();i++){JSONObject phase=phases.getJSONObject(i);JSONArray items=phase.getJSONArray("items");for(int j=0;j<items.length();j++)steps.put(new JSONObject(items.getJSONObject(j).toString()).put("phase_id",phase.getString("phase_id")).put("kind",phase.getString("type")));}
  s=new JSONObject().put("history",history).put("schema_version",2).put("task",t).put("manifest",wrapper.getJSONObject("manifest")).put("steps",steps).put("index",0).put("state","waiting_start").put("run_epoch",wrapper.getInt("run_epoch")).put("session_id",UUID.randomUUID().toString()).put("sequence",0).put("state_revision",0).put("actual_repeats",0).put("cycle_repeats",0).put("events",new JSONArray()).put("commands",new JSONObject()).put("acked",0);
  leaseUntil=clock.now()+15000;event("task_received",null);render();return status();
 }
 private void scope(JSONObject x)throws Exception{if(s==null||!task().getString("task_id").equals(x.getString("task_id"))||!task().getString("content_hash").equals(x.getString("content_hash"))||s.getInt("run_epoch")!=x.getInt("run_epoch"))throw new IllegalArgumentException("task_scope");}
 public synchronized JSONObject events(JSONObject x)throws Exception{scope(x);long after=x.optLong("after_sequence",x.optLong("after",0));int limit=x.optInt("limit",100);if(after<0||limit<1||limit>1000)throw new IllegalArgumentException("event_range");JSONArray result=new JSONArray(),all=s.getJSONArray("events");for(int i=0;i<all.length()&&result.length()<limit;i++)if(all.getJSONObject(i).getLong("sequence")>after)result.put(all.get(i));return new JSONObject().put("events",result);}
 public synchronized JSONObject ack(JSONObject x)throws Exception{scope(x);long through=x.getLong("through_sequence");if(through<s.getLong("acked")||through>s.getLong("sequence"))throw new IllegalArgumentException("ack_range");JSONArray keep=new JSONArray(),all=s.getJSONArray("events");for(int i=0;i<all.length();i++)if(all.getJSONObject(i).getLong("sequence")>through)keep.put(all.get(i));s.put("events",keep).put("acked",through);save();if(keep.length()==0&&!active())assets.release(task().getString("task_id"),task().getString("content_hash"));return new JSONObject().put("through_sequence",through);}
 public synchronized JSONObject lease(JSONObject x)throws Exception{scope(x);long ms=x.getLong("lease_ms");if(ms<1||ms>15000)throw new IllegalArgumentException("lease_range");leaseUntil=clock.now()+ms;return new JSONObject().put("lease_ms",ms);}
 public synchronized void pause(String reason)throws Exception{if(!active()||s.getString("state").equals("paused"))return;generation++;nextRepeat=0;audio.stop();s.put("state","paused").put("pause_reason",safeReason(reason));event("paused",null);render();}
 private String safeReason(String r){return Arrays.asList("foreground_exit","service_stop","focus_loss","lease_expired").contains(r)?r:"control";}
 private boolean manual()throws Exception{return task().getJSONObject("playback").optBoolean("manual_navigation")&&current().getString("kind").equals("dictation");}
 private void enter(String command)throws Exception{
  // Commit the confirmed cursor before starting the next item's audio.
  if(batch){batch=false;save();}
  reminder=false;remindAt=clock.now()+60000;s.put("cycle_repeats",0).put("cycle_target",replayOnce||manual()?1:task().getJSONObject("playback").getInt("repeat_count"));replayOnce=false;if(current().getString("kind").equals("recognition")){planPage();s.put("state","presenting");event("page_presented",command);s.put("state","waiting_child");event("waiting_child",null);render();}else play(command);
 }
 private JSONArray phasePages()throws Exception{
  JSONArray candidates=new JSONArray();String phase=current().getString("phase_id");int begin=s.getInt("index");while(begin>0&&steps().getJSONObject(begin-1).getString("phase_id").equals(phase))begin--;
  for(int i=begin;i<steps().length()&&steps().getJSONObject(i).getString("phase_id").equals(phase);i++)candidates.put(steps().getJSONObject(i));
  return WordPageLayout.largePages(candidates,width,Math.max(200,height-360));
 }
 private int phaseBegin()throws Exception{int begin=s.getInt("index");String phase=current().getString("phase_id");while(begin>0&&steps().getJSONObject(begin-1).getString("phase_id").equals(phase))begin--;return begin;}
 private void planPage()throws Exception{JSONArray pages=phasePages();int begin=phaseBegin(),index=s.getInt("index");for(int n=0;n<pages.length();n++){int end=begin+pages.getJSONArray(n).length()-1;if(index<=end){s.put("page_end",end);return;}begin=end+1;}}
 private void previousPage()throws Exception{JSONArray pages=phasePages();int begin=phaseBegin(),previous=begin,index=s.getInt("index");for(int n=0;n<pages.length();n++){int end=begin+pages.getJSONArray(n).length()-1;if(index<=end){s.put("index",previous);return;}previous=begin;begin=end+1;}}
 private void play(String command)throws Exception{
  final long token=++generation;s.put("state","playing");event("playback_started",command);render();JSONObject t=task();audio.play(t.getString("task_id"),t.getString("content_hash"),current().getString("audio_asset_id"),1,new DictationEngine.Completion(){public void done(boolean drained){synchronized(DictationEngineV2.this){if(token!=generation||!s.optString("state").equals("playing"))return;try{if(!drained){s.put("state","failed_item");event("item_failed",null);render();return;}s.put("actual_repeats",s.getInt("actual_repeats")+1).put("cycle_repeats",s.getInt("cycle_repeats")+1);event("playback_completed",null);if(s.getInt("cycle_repeats")>=s.getInt("cycle_target")){s.put("state","waiting_child");remindAt=clock.now()+60000;event("waiting_child",null);render();}else{nextRepeat=clock.now()+task().getJSONObject("playback").getLong("interval_ms");save();}}catch(Exception ignored){generation++;audio.stop();try{s.put("state","failed_item");event("item_failed",null);render();}catch(Exception ignored2){}}}}});
 }
 public synchronized void tick()throws Exception{if(!active())return;if(leaseUntil>0&&clock.now()>=leaseUntil&&!s.getString("state").equals("paused")){pause("lease_expired");return;}if(s.getString("state").equals("waiting_child")&&clock.now()>=remindAt){reminder=true;remindAt=clock.now()+60000;render();}if(nextRepeat>0&&clock.now()>=nextRepeat&&s.getString("state").equals("playing")){nextRepeat=0;play(null);}}
 public synchronized JSONObject localControl(String action)throws Exception{if(action.equals("resume")&&s!=null&&s.getString("state").equals("paused")&&s.optBoolean("remote_pause_lock")){event("resume_requested",null);render();return status();}JSONObject item=current();JSONObject x=new JSONObject().put("schema_version",2).put("task_id",task().getString("task_id")).put("content_hash",task().getString("content_hash")).put("run_epoch",s.getInt("run_epoch")).put("expected_state_revision",s.getLong("state_revision")).put("phase_id",item.getString("phase_id")).put("item_id",item.getString("item_id")).put("command_id",UUID.randomUUID().toString()).put("action",action);localCommand=true;try{return control(x);}finally{localCommand=false;}}
 public synchronized JSONObject control(JSONObject x)throws Exception{
  scope(x);String id=x.getString("command_id"),fingerprint=DictationSpec.canonical(x);JSONObject commands=s.getJSONObject("commands");if(commands.has(id)){if(!commands.getString(id).equals(fingerprint))throw new IllegalArgumentException("command_conflict");return status();}
  if(x.getInt("schema_version")!=2||x.getLong("expected_state_revision")!=s.getLong("state_revision")||!current().getString("phase_id").equals(x.getString("phase_id"))||!current().getString("item_id").equals(x.getString("item_id")))throw new IllegalArgumentException("stale_context");if(!active())throw new IllegalArgumentException("task_terminal");String action=x.getString("action"),state=s.getString("state");
  if(!(action.equals("start")&&state.equals("waiting_start")||action.equals("confirm")&&(state.equals("waiting_child")||manual()&&state.equals("playing"))||action.equals("pause")||action.equals("resume")&&state.equals("paused")||action.equals("replay")&&(Arrays.asList("waiting_child","failed_item").contains(state)||manual()&&state.equals("playing"))||action.equals("previous")&&(manual()&&Arrays.asList("waiting_child","playing","failed_item").contains(state)||current().getString("kind").equals("recognition")&&state.equals("waiting_child"))||action.equals("cancel")))throw new IllegalArgumentException("invalid_action");
  if(Arrays.asList("start","confirm","resume","replay","previous").contains(action)&&explanationBusy())throw new IllegalStateException("explanation_audio_busy");
  if(Arrays.asList("start","confirm","resume","replay","previous").contains(action)&&(leaseUntil==0||clock.now()>=leaseUntil)){pause("lease_expired");throw new IllegalStateException("device_disconnected");}
  if(commands.length()>=4096)throw new IllegalArgumentException("command_capacity");commands.put(id,fingerprint);generation++;audio.stop();nextRepeat=0;
  if(action.equals("pause")){s.put("remote_pause_lock",s.optBoolean("remote_pause_lock")||!localCommand).put("state","paused");event("paused",id);render();}
  else if(action.equals("cancel")){s.put("state","cancelled");event("cancelled",id);render();}
  else if(action.equals("previous")){
   if(current().getString("kind").equals("recognition"))previousPage();else{int index=s.getInt("index");if(index>0&&steps().getJSONObject(index-1).getString("kind").equals("dictation"))s.put("index",index-1).put("actual_repeats",0);}
   s.put("state","presenting");event("navigated_previous",id);save();replayOnce=true;enter(null);
  }
  else if(action.equals("confirm")){batch=true;int end=current().getString("kind").equals("recognition")?s.getInt("page_end"):s.getInt("index");while(s.getInt("index")<end){event("item_confirmed",id);s.put("index",s.getInt("index")+1);}event("item_confirmed",id);if(s.getInt("index")+1==steps().length()){s.put("state","completed");event("task_completed",id);render();}else{s.put("index",s.getInt("index")+1).put("actual_repeats",0);enter(null);}}
  else {replayOnce=action.equals("replay")&&state.equals("waiting_child");if(action.equals("resume")){validateAssets(task(),s.getJSONObject("manifest"));s.put("remote_pause_lock",false).put("state","presenting");event("resumed",id);}else if(action.equals("replay")){s.put("state","presenting");event("replayed",id);}enter(action.equals("start")?id:null);}batch=false;save();return status();
 }
 public synchronized void render()throws Exception{if(s==null)return;String state=s.getString("state"),kind=current().getString("kind");JSONArray words=new JSONArray();if(kind.equals("recognition")&&Arrays.asList("presenting","waiting_child").contains(state)){for(int i=s.getInt("index");i<=s.optInt("page_end",s.getInt("index"));i++)words.put(new JSONObject().put("text",steps().getJSONObject(i).getString("text")));}JSONObject presentation=DictationPresentation.describe(s);String text=presentation.getString("title")+"\n"+presentation.getString("subtitle")+"\n"+presentation.getString("progress");StringBuilder log=new StringBuilder();if(debug){JSONArray events=s.optJSONArray("safe_log");if(events==null)events=new JSONArray();for(int j=Math.max(0,events.length()-5);j<events.length();j++){JSONObject e=events.getJSONObject(j);log.append("\n#").append(e.getLong("sequence")).append(" ").append(e.getString("action")).append(" / ").append(e.getString("state")).append(" · 播报 ").append(e.getInt("actual_repeats"));}}display.show("v2_"+state,words,text+log.toString());}
}
